            ? await gprsModems.readerOptions({ identifier: GPRS_MODEM_ID, line: GPRS_LINE, responseTimeoutMs: RESPONSE_TIMEOUT_MS })
            : { host: HOST, port: PORT };
        const deviceState = await withConnectionLock(GPRS_MODEM_ID ? 'gprs' : HOST, GPRS_MODEM_ID || PORT, async () => {
            const client = new Spt941Client({
                address: ADDRESS,
                serialNumber: SERIAL_NUMBER,
                responseTimeoutMs: RESPONSE_TIMEOUT_MS,
                ...transport,
            });
            // Spt941Client.read() opens the socket, starts the session, reads
            // the settings, clock, flags, current values and totals and closes the socket itself.
            return await client.read();
        });

        msg.payload = deviceState;
        node.send(msg);
        node.status({ fill: 'green', shape: 'dot', text: 'ok ' + new Date().toLocaleTimeString() });
    } catch (err) {
        // Full read failed — nothing goes out. No partial/incomplete set is sent downstream.
        node.error('SPT941 read failed: ' + err.message, msg);
        node.status({ fill: 'red', shape: 'ring', text: 'error' });
    }
})();

return null;

